/**
 * /platform/sms/ —— SMS 通道详情页
 *
 * 🔴 **本页是「通道范围」表述最密集的地方**。它只讲 SMS，且每一段都要自证这一点 ——
 *    因为 BSP 文案稿 §6 的两条禁令，正是「把短信独有的能力写成了三通道通用」。
 *    改本页前先读 `sms-platform/docs/BSP角色与免责边界-对外文案稿.md` §6。
 *
 * 🔴 本页刻意**不写「支持 N 家供应商」**这种孤立数字：渠道数有两个口径
 *    （SDK 适配器 33 / 控制台可自助 6），混着写就是虚标。要写数字就写明口径，
 *    或直接指向 `/integrations/`（那里每一条都能指到 `PROVIDER_SPECS`）。
 *
 * 🔴 `softwareApp={false}`：本页不属于 Whaleal Cart 这个 Shopify 应用。
 *
 * 🔴 **2026-10-14 加「What people send on it」段**（用户裁决：营销页要讲「客户怎么用」）。
 *    放在首屏之后、能力卡之前 —— 先让读者认出自己的业务，再讲平台能做什么。
 *    标题/角标/摘要全部来自 `data/useCases.js`，本页不另写一份（防漂移）。
 *
 * @author 恒哥
 * @since 2026-10-12
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import { MESSAGING_PRODUCT_NAME, MESSAGING_CONSOLE_URL, MESSAGING_CONNECTIONS_URL } from '../../constants/brand';
import { INTEGRATION_STATS } from '../../data/integrations';
import { USE_CASES } from '../../data/useCases';
import { FAMILIES } from '../../data/families';
import '../../styles/marketing.css';
import T from '../../i18n/LocalizedText';
import { usePageI18n } from '../../i18n';

/**
 * 「这个通道平时在跑什么」—— 本页原本只有能力卡（讲平台能做什么），
 * 没有一段讲客户拿它做什么。标题/角标/摘要全部取自 `data/useCases.js`（单一来源），
 * 只有 `to` 在这里拼，避免手写标题与 `/use-cases/` 的页名漂移。
 */
const JOB_SLUGS = [
  'order-confirmations',
  'one-time-passwords',
  'appointment-reminders',
  'service-and-incident-alerts',
];

const USE_CASE_BASE = FAMILIES['use-cases'].indexPath;

const JOBS = JOB_SLUGS.map((slug) => {
  const uc = USE_CASES.find((u) => u.slug === slug);
  return uc ? { ...uc, to: `${USE_CASE_BASE}${slug}/` } : null;
}).filter(Boolean);

const PILLARS = [
  {
    title: 'Routing and failover',
    body: 'Ordered connections with per-connection weights across sender numbers. A provider that keeps rejecting sends is taken out of rotation instead of being retried forever.',
    to: '/guides/routing-failover/',
  },
  {
    title: 'Pacing to your real quota',
    body: 'Each connection carries a send rate and the platform queues to it. A throttle is treated as a pacing signal, not as a failed send.',
    to: '/guides/pacing/',
  },
  {
    title: 'Delivery receipts',
    body: 'Provider callbacks are normalized into one status vocabulary, with the raw provider code kept alongside. Terminal outcomes only.',
    to: '/guides/delivery-receipts/',
  },
  {
    title: 'Opt-out suppression',
    body: 'A reply of STOP writes a suppression record, and a check runs before each marketing send. Enforcement is fail-closed by default for marketing traffic.',
    to: '/guides/opt-out/',
  },
  {
    title: 'Encoding and segment accounting',
    body: 'GSM-7 or UCS-2, decided per connection, with the billable segment count kept on the record so it can be reconciled against your provider invoice.',
    to: '/guides/sms-segments/',
  },
  {
    title: 'Bring your own account',
    body: 'The platform holds no provider account. Your credentials, your quota, your numbers, your invoice.',
    to: '/guides/byol/',
  },
];

export default function MessagingSmsPage(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={`SMS over your own provider \u2014 ${MESSAGING_PRODUCT_NAME}`}
        description={`SMS with routing and failover, per-connection pacing, normalized receipts, opt-out suppression and segment accounting — on the CPaaS account you already hold.`}
        pathname="/platform/sms/"
        softwareApp={false}
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: MESSAGING_PRODUCT_NAME, path: '/platform/' },
          { name: 'SMS', path: '/platform/sms/' },
        ]} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="platform_sms.001">SMS channel</T></span>
          <h1><T id="platform_sms.002">SMS, without moving your provider</T></h1>
          <p className="mk-lead"><T id="platform_sms.003">
            SMS is the channel this platform was built around, and the one that carries the fullest
            set of channel-level capabilities. Email and WhatsApp connect on the same model; this
            page covers SMS. You keep your CPaaS account, and you get the layer above it that a
            single provider account does not give you.
          </T></p>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={MESSAGING_CONNECTIONS_URL}><T id="platform_sms.004">
              Add an SMS connection
            </T></a>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/integrations/")}><T id="platform_sms.005">
              Browse provider integrations
            </T></Link>
          </div>
        </header>

        <section className="mk-section">
          <h2><T id="platform_sms.006">What people send on it</T></h2>
          <p className="mk-section-lead"><T id="platform_sms.007">
            In practice the channel is carrying one of a handful of message types. Each has its own
            page covering what the message has to carry, how it should be paced, and what is worth
            recording afterwards.
          </T></p>
          <div className="mk-grid">
            {JOBS.map((j) => (
              <article className="mk-card" key={j.slug}>
                <span className="mk-card-tag">{j.eyebrow}</span>
                <h3>{j.name}</h3>
                <p>{j.lede}</p>
                <Link className="mk-card-link" to={j.to}><T id="platform_sms.008">
                  Read more &rarr;
                </T></Link>
              </article>
            ))}
          </div>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-secondary" to={USE_CASE_BASE}><T id="platform_sms.009">
              All use cases
            </T></Link>
            <Link className="mk-btn mk-btn-secondary" to={FAMILIES.industries.indexPath}><T id="platform_sms.010">
              Browse by industry
            </T></Link>
          </div>
        </section>

        <section className="mk-section">
          <h2><T id="platform_sms.011">What sits on top</T></h2>
          <div className="mk-grid">
            {PILLARS.map((p) => (
              <article className="mk-card" key={p.title}>
                <h3>{p.title}</h3>
                <p>{p.body}</p>
                <Link className="mk-card-link" to={p.to}><T id="platform_sms.012">
                  Read the guide &rarr;
                </T></Link>
              </article>
            ))}
          </div>
        </section>

        <section className="mk-section">
          <h2><T id="platform_sms.013">Where it plugs in</T></h2>
          <p className="mk-section-lead">
            <T id="platform_sms.014">{INTEGRATION_STATS.byChannel.SMS} SMS providers can be connected self-service today, each
            with the credential fields it actually needs listed on its own page. Beneath the
            self-service set is an SMS adapter library of {INTEGRATION_STATS.sdkAdapters}{' '}
            adapters; those outside the listed set are unlocked on request rather than
            self-service, so we describe them as a different thing.
          </T></p>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-secondary" to={localePath("/integrations/")}><T id="platform_sms.015">
              See what each provider needs
            </T></Link>
          </div>
        </section>

        <div className="mk-scope">
          <T id="platform_sms.016"><strong>Scope.</strong> What is SMS-specific, and described on this page: routing and
          automatic failover, per-number pacing, and encoding / segment accounting. Delivery receipts
          are normalized on all three channels &mdash; every SMS provider, Resend on email and Meta on
          WhatsApp &mdash; and opt-out suppression is applied to marketing sends on all three, with
          the automatic STOP-keyword path being the SMS one.
        </T></div>

        <section className="mk-section">
          <h2><T id="platform_sms.017">How a send works</T></h2>
          <ol className="mk-steps">
            <li>
              <h3><T id="platform_sms.018">You hand us a message</T></h3>
              <p><T id="platform_sms.019">
                Through the console or the API, naming the recipient, the content and — for marketing
                traffic — the message type that decides whether the suppression check applies.
              </T></p>
            </li>
            <li>
              <h3><T id="platform_sms.020">We pick a route</T></h3>
              <p><T id="platform_sms.021">
                The healthiest, highest-priority connection that is still inside its pacing budget
                takes the message. Sender numbers on that connection rotate by weight.
              </T></p>
            </li>
            <li>
              <h3><T id="platform_sms.022">We call your provider</T></h3>
              <p><T id="platform_sms.023">
                With your credentials, against your account, at the rate your quota allows. Nothing
                is sent on our account and nothing lands on our invoice to your provider.
              </T></p>
            </li>
            <li>
              <h3><T id="platform_sms.024">We record the outcome</T></h3>
              <p><T id="platform_sms.025">
                The provider acceptance, and later its delivery receipt, are recorded against the
                message with the error code normalized. Message bodies are not stored.
              </T></p>
            </li>
          </ol>
        </section>

        <section className="mk-section">
          <h2><T id="platform_sms.026">What stays with your provider</T></h2>
          <p className="mk-section-lead"><T id="platform_sms.027">
            The account is yours, so these stay on your side of the line. We hand every message over
            correctly and report what came back &mdash; the carrier relationship is the provider&rsquo;s job.
          </T></p>
          <ul className="mk-list mk-list-plain">
            <li><T id="platform_sms.028">Registering sender IDs, numbers or short codes with carriers</T></li>
            <li><T id="platform_sms.029">The quota your provider grants your account</T></li>
            <li><T id="platform_sms.030">Reach to a given handset, which depends on the destination carrier</T></li>
          </ul>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={MESSAGING_CONSOLE_URL}><T id="platform_sms.031">
              Open the console
            </T></a>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/platform/roadmap/")}><T id="platform_sms.032">
              Channels &amp; status
            </T></Link>
          </div>
        </section>
      </div>
    </Layout>
  );
}
